-- Catalog: replace all products with the Willow, Hazel and Elegance Essentials towel collections (built from HW_PIM (1).xlsx + OVERALL SKU+PRICE).
-- The previous store is kept in public.store_backups first.
create table if not exists public.store_backups (id bigserial primary key, taken_at timestamptz not null default now(), note text, data jsonb not null);
alter table public.store_backups enable row level security;
revoke all on public.store_backups from anon, authenticated;
insert into public.store_backups (note, data) select 'before towel collections 2026-09-19', data from public.store where id = 'main';
